def find_max(numbers):
    if not numbers:
        raise ValueError("numbers 不可為空")

    best = numbers[0]
    for value in numbers[1:]:
        if value > best:
            best = value
    return best

def contains(numbers, target):
    for value in numbers:
        if value == target:
            return True
    return False

def all_pairs(left, right):
    pairs = []
    for first in left:
        for second in right:
            pairs.append((first, second))
    return pairs

def recursive_sum(numbers, index=0):
    if index == len(numbers):
        return 0
    return numbers[index] + recursive_sum(numbers, index + 1)
